import { getCustomer } from './customers.js';
import { formatEuros } from './money.js';
import { lineTotal, invoiceTotals } from './invoices.js';

/**
 * Render an invoice as plain text.
 * @param {{ customerId: string, issueDate: string, status: string, number?: string, lines: Array }} invoice
 * @returns {string} Plain-text invoice
 */
export function renderInvoiceText(invoice) {
  const number = invoice.number || 'DRAFT';

  const customerResult = getCustomer(invoice.customerId);
  const customerName = customerResult.ok ? customerResult.value.name : 'Unknown Customer';

  const lines = [number, customerName];

  for (const line of invoice.lines) {
    const total = lineTotal(line);
    const lineText = `${line.qty}× ${line.name} @ ${formatEuros(line.unitPrice)} = ${formatEuros(total)}`;
    lines.push(lineText);
  }

  const { subtotal, discount, vat, voucher, total } = invoiceTotals(invoice);

  if (subtotal > 0) {
    lines.push(`Subtotal: ${formatEuros(subtotal)}`);
  }

  if (discount > 0) {
    lines.push(`Discount: ${formatEuros(discount)}`);
  }

  if (vat > 0) {
    lines.push(`VAT: ${formatEuros(vat)}`);
  }

  if (voucher > 0) {
    lines.push(`Voucher: ${formatEuros(voucher)}`);
  }

  lines.push(`Total: ${formatEuros(total)}`);

  return lines.join('\n');
}

