import { getCustomer } from './customers.js';
import { formatEuros } from './money.js';
import { lineTotal, lineDiscount, invoiceTotals } from './invoices.js';

/**
 * Render an invoice as plain text.
 * @param {{ customerId: string, issueDate: string, status: string, number?: string, lines: Array, dueDate?: string, payments?: Array, voucher?: { code: string, amount: number } }} invoice
 * @returns {string} Plain-text invoice
 */
export function renderInvoiceText(invoice) {
  const number = invoice.number || 'DRAFT';

  const customerResult = getCustomer(invoice.customerId);
  const customerName = customerResult.ok ? customerResult.value.name : 'Unknown Customer';

  const lines = [number, customerName];

  for (const line of invoice.lines) {
    const total = lineTotal(line);
    const lineText = `${line.qty}× ${line.name} @ ${formatEuros(line.unitPrice)} = ${formatEuros(total)}`;
    lines.push(lineText);

    const discount = lineDiscount(line);
    if (discount > 0) {
      lines.push(`  Discount: ${formatEuros(discount)}`);
    }
  }

  const { subtotal, discount: totalDiscount, vat, voucher, total } = invoiceTotals(invoice);

  if (subtotal > 0) {
    lines.push(`Subtotal: ${formatEuros(subtotal)}`);
  }

  if (totalDiscount > 0) {
    lines.push(`Discount: ${formatEuros(totalDiscount)}`);
  }

  if (vat > 0) {
    lines.push(`VAT: ${formatEuros(vat)}`);
  }

  if (voucher > 0) {
    lines.push(`Voucher: ${formatEuros(voucher)}`);
  }

  lines.push(`Total: ${formatEuros(total)}`);

  if (invoice.dueDate) {
    lines.push(`Due: ${invoice.dueDate}`);
  }

  if (invoice.payments && invoice.payments.length > 0) {
    const totalPaid = invoice.payments.reduce((sum, p) => sum + p.amount, 0);
    lines.push(`Paid: ${formatEuros(totalPaid)}`);
  }

  return lines.join('\n');
}

