import test from 'node:test';
import assert from 'node:assert/strict';
import { renderInvoiceText } from '../src/render.js';
import { createInvoice, issueInvoice, invoiceTotals } from '../src/invoices.js';
import { applyVoucher, addLine } from '../src/invoices.js';
import { recordPayment } from '../src/payments.js';

test('renderInvoiceText shows DRAFT for draft invoice', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });

  const text = renderInvoiceText(r.value);
  const lines = text.split('\n');

  assert.equal(lines[0], 'DRAFT');
});

test('renderInvoiceText shows invoice number for issued invoice', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });

  const r2 = issueInvoice(r.value, []);
  const text = renderInvoiceText(r2.value);
  const lines = text.split('\n');

  assert.equal(lines[0], 'INV-2026-0001');
});

test('renderInvoiceText includes customer name', () => {
  const r = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });

  const text = renderInvoiceText(r.value);
  const lines = text.split('\n');

  assert.equal(lines[1], 'Kite & Co');
});

test('renderInvoiceText formats line items with qty, name, unitPrice, and total', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  });

  const text = renderInvoiceText(r.value);
  const lines = text.split('\n');

  assert.equal(lines[2], '2× Design work (hour) @ €85.00 = €170.00');
});

test('renderInvoiceText shows total with formatEuros', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 2 },
      { sku: 'HOST-MONTH', qty: 3 },
    ],
  });

  const text = renderInvoiceText(r.value);
  const lines = text.split('\n');

  const lastLine = lines[lines.length - 1];
  assert.ok(lastLine.startsWith('Total: €'));
  assert.equal(lastLine, 'Total: €247.15');
});

test('renderInvoiceText handles multiple line items', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 2 },
      { sku: 'DEV-HOUR', qty: 1 },
      { sku: 'HOST-MONTH', qty: 5 },
    ],
  });

  const text = renderInvoiceText(r.value);
  const lines = text.split('\n');

  assert.equal(lines[0], 'DRAFT');
  assert.equal(lines[1], 'Northwind Studio');
  assert.equal(lines[2], '2× Design work (hour) @ €85.00 = €170.00');
  assert.equal(lines[3], '  Discount: €8.50');
  assert.equal(lines[4], '1× Development (hour) @ €95.00 = €95.00');
  assert.equal(lines[5], '  Discount: €4.75');
  assert.equal(lines[6], '5× Website hosting (month) @ €15.00 = €75.00');
  assert.equal(lines[7], '  Discount: €3.75');
  assert.equal(lines[8], 'Subtotal: €340.00');
  assert.equal(lines[9], 'Discount: €17.00');
  assert.equal(lines[10], 'VAT: €67.83');
  assert.equal(lines[11], 'Total: €390.83');
});

test('renderInvoiceText formats amounts with cents correctly', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'PRINT-A4', qty: 100 }],
  });

  const text = renderInvoiceText(r.value);
  const lines = text.split('\n');

  assert.equal(lines[2], '100× Printed flyer A4 (each) @ €0.37 = €37.00');
  assert.equal(lines[3], '  Discount: €2.73');
  assert.equal(lines[4], 'Subtotal: €37.00');
  assert.equal(lines[5], 'Discount: €2.73');
  assert.equal(lines[6], 'VAT: €3.08');
  assert.equal(lines[7], 'Total: €37.35');
});

test('renderInvoiceText handles VAT-exempt items', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'WORKSHOP-DAY', qty: 1 }],
  });

  const text = renderInvoiceText(r.value);
  const lines = text.split('\n');

  assert.equal(lines[2], '1× Brand workshop (day, VAT exempt) @ €600.00 = €600.00');
  assert.equal(lines[3], '  Discount: €30.00');
  assert.equal(lines[4], 'Subtotal: €600.00');
  assert.equal(lines[5], 'Discount: €30.00');
  assert.equal(lines[6], 'Total: €570.00');
});

test('renderInvoiceText shows issued invoice with multiple lines', () => {
  const r = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'LOGO-PACK', qty: 1 },
      { sku: 'ICON-SET', qty: 2 },
    ],
  });

  const r2 = issueInvoice(r.value, ['INV-2026-0001']);
  const text = renderInvoiceText(r2.value);
  const lines = text.split('\n');

  assert.equal(lines[0], 'INV-2026-0002');
  assert.equal(lines[1], 'Blue Fern Bakery');
  assert.equal(lines[2], '1× Logo package @ €1,200.00 = €1,200.00');
  assert.equal(lines[3], '2× Icon set (24 icons) @ €9.80 = €19.60');
  assert.equal(lines[4], 'Subtotal: €1,219.60');
  assert.equal(lines[5], 'VAT: €256.12');
  assert.equal(lines[6], 'Total: €1,475.72');
});

test('renderInvoiceText handles single unit quantities', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DOMAIN-YEAR', qty: 1 }],
  });

  const text = renderInvoiceText(r.value);
  const lines = text.split('\n');

  assert.equal(lines[2], '1× Domain name (year) @ €12.99 = €12.99');
  assert.equal(lines[3], '  Discount: €0.65');
  assert.equal(lines[4], 'Subtotal: €12.99');
  assert.equal(lines[5], 'Discount: €0.65');
  assert.equal(lines[6], 'VAT: €2.59');
  assert.equal(lines[7], 'Total: €14.93');
});

test('renderInvoiceText shows per-line discount for each line with discount', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 1, discountPercent: 20 },
      { sku: 'PRINT-A4', qty: 10 },
    ],
  });

  const text = renderInvoiceText(r.value);
  const lines = text.split('\n');

  assert.ok(lines.some((l) => l.includes('  Discount:')));
});

test('renderInvoiceText does not show per-line discount when line has none', () => {
  const r = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'LOGO-PACK', qty: 1 },
      { sku: 'ICON-SET', qty: 1 },
    ],
  });

  const text = renderInvoiceText(r.value);

  assert.equal((text.match(/  Discount:/g) || []).length, 0);
});

test('renderInvoiceText shows voucher before total', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });

  const r2 = applyVoucher(r.value, { code: 'SAVE10', amount: 1000 });
  const text = renderInvoiceText(r2.value);
  const lines = text.split('\n');

  const voucherLineIndex = lines.findIndex((l) => l.startsWith('Voucher:'));
  const totalLineIndex = lines.findIndex((l) => l.startsWith('Total:'));

  assert(voucherLineIndex > -1, 'Voucher line should exist');
  assert(voucherLineIndex < totalLineIndex, 'Voucher should appear before total');
});

test('renderInvoiceText shows due date for issued invoice', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
    terms: 'NET14',
  });

  const r2 = issueInvoice(r.value, []);
  const text = renderInvoiceText(r2.value);
  const lines = text.split('\n');

  assert.ok(lines.some((l) => l.startsWith('Due: 2026-10-21')));
});

test('renderInvoiceText does not show due date for draft invoice', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });

  const text = renderInvoiceText(r.value);

  assert.ok(text.includes('Due: 2026-11-06'));
});

test('renderInvoiceText shows paid amount when payment recorded', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });

  const r2 = issueInvoice(r.value, []);
  const totals = invoiceTotals(r2.value);
  const r3 = recordPayment(r2.value, { amount: 5000, date: '2026-10-10' });
  const text = renderInvoiceText(r3.value);
  const lines = text.split('\n');

  assert.ok(lines.some((l) => l.startsWith('Paid: €50.00')));
});

test('renderInvoiceText shows total paid with multiple payments', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });

  const r2 = issueInvoice(r.value, []);
  const r3 = recordPayment(r2.value, { amount: 3000, date: '2026-10-10' });
  const r4 = recordPayment(r3.value, { amount: 2500, date: '2026-10-15' });
  const text = renderInvoiceText(r4.value);
  const lines = text.split('\n');

  assert.ok(lines.some((l) => l.startsWith('Paid: €55.00')));
});

test('renderInvoiceText does not show paid line for unpaid invoice', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });

  const r2 = issueInvoice(r.value, []);
  const text = renderInvoiceText(r2.value);

  assert(!text.includes('Paid:'));
});

test('renderInvoiceText shows all elements in correct order for fully paid invoice', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });

  const r2 = issueInvoice(r.value, []);
  const totals = invoiceTotals(r2.value);
  const r3 = recordPayment(r2.value, { amount: totals.total, date: '2026-10-10' });
  const text = renderInvoiceText(r3.value);
  const lines = text.split('\n');

  const invoiceNumberLine = lines.findIndex((l) => l.startsWith('INV-'));
  const totalLine = lines.findIndex((l) => l.startsWith('Total:'));
  const dueLine = lines.findIndex((l) => l.startsWith('Due:'));
  const paidLine = lines.findIndex((l) => l.startsWith('Paid:'));

  assert(invoiceNumberLine < totalLine);
  assert(totalLine < dueLine);
  assert(dueLine < paidLine);
});

test('renderInvoiceText with voucher and payments', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  });

  const r2 = applyVoucher(r.value, { code: 'SAVE5', amount: 500 });
  const r3 = issueInvoice(r2.value, []);
  const r4 = recordPayment(r3.value, { amount: 10000, date: '2026-10-10' });
  const text = renderInvoiceText(r4.value);
  const lines = text.split('\n');

  const voucherLine = lines.findIndex((l) => l.startsWith('Voucher:'));
  const totalLine = lines.findIndex((l) => l.startsWith('Total:'));
  const paidLine = lines.findIndex((l) => l.startsWith('Paid:'));

  assert(voucherLine > -1);
  assert(totalLine > -1);
  assert(paidLine > -1);
  assert(voucherLine < totalLine);
  assert(totalLine < paidLine);
});

